function decodeAkamaiConfigRule(attackData) {

    let decodedAttackData = {};

    for (const [key, value] of Object.entries(attackData)) {
        if (key.match(/^rules?/i)) {

            // Akamai joins the per-rule values with ';'. A trailing ';' would produce a
            // spurious empty member, so strip it. base64 uses [A-Za-z0-9+/=] only, so a
            // semicolon is always a separator and never part of a value.
            // Leading/interior empties are meaningful placeholders and are preserved,
            // because the rule* arrays are positionally aligned with each other.
            const decoded = String(C.Decode.uri(value)).replace(/;+$/, '');

            if (decoded !== '') {
                decodedAttackData[key] = Array.from(decoded.split(';'), (x) => C.Decode.base64(x));
            }

            delete attackData[key];
        }
    }

    return decodedAttackData;
}

function mergeAkamaiConfigData(configData) {
    let mergedData = [];

    for (const [key, value] of Object.entries(configData)) {

        let formattedKey = key.replace(/^rule(\w{2,})$/i, '$1').replace(/s$/i, '');
        formattedKey = (formattedKey.toLowerCase() === 'rule' ? 'Rule' : formattedKey);

        for (let i = 0; i < value.length; i++) {
            if (!mergedData[i]) {
                mergedData[i] = {};
            }
            if (value[i] !== undefined && value[i] !== '') {
                mergedData[i][formattedKey] = value[i];
            }
        }
    }

    // Drop rule slots that carry no values at all, so a trailing or all-empty
    // member does not surface as an empty object in attackData.rules.
    return mergedData.filter((rule) => rule && Object.keys(rule).length > 0);
}

